import{_ as t,c as a,o as n,ag as r}from"./chunks/framework.Vyheyqg9.js";const p=JSON.parse('{"title":"Practice: Why should we invest in automated testing?","description":"","frontmatter":{},"headers":[],"relativePath":"practice/engineering/testing/Why_should_we_invest_in_automated_testing.md","filePath":"practice/engineering/testing/Why_should_we_invest_in_automated_testing.md"}'),s={name:"practice/engineering/testing/Why_should_we_invest_in_automated_testing.md"};function i(o,e,c,d,l,h){return n(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="practice-why-should-we-invest-in-automated-testing" tabindex="-1">Practice: Why should we invest in automated testing? <a class="header-anchor" href="#practice-why-should-we-invest-in-automated-testing" aria-label="Permalink to “Practice: Why should we invest in automated testing?”">​</a></h1><p><strong>Learner status: outstanding.</strong> Author verification does not complete these criteria.</p><p>Prerequisite: <a href="./../../../senior_growth/Testing/Why_should_we_invest_in_automated_testing.html">the worked lesson</a> and <a href="./../">the shared sequence</a>. Reuse the mapped existing project rather than build an application per note.</p><h2 id="scope-observable-acceptance-and-failure-cases" tabindex="-1"><span class="hub-section-number">1 </span>Scope, observable acceptance and failure cases <a class="header-anchor" href="#scope-observable-acceptance-and-failure-cases" aria-label="Permalink to “1 Scope, observable acceptance and failure cases”">​</a></h2><p><strong>Exercise acceptance:</strong> choose one load and one authorization threat scenario, state the cost of missing the failure, implement them in the primary project, retain raw failures/results and fix the underlying issue. Compare test maintenance/runtime against risk reduction; no invented monetary ROI or production result. Learner practice remains required. References: <a href="https://grafana.com/docs/k6/latest/using-k6/thresholds/" target="_blank" rel="noreferrer">k6 thresholds</a>, <a href="https://grafana.com/docs/k6/latest/using-k6/k6-options/reference/" target="_blank" rel="noreferrer">k6 test options</a>, <a href="https://owasp.org/www-project-web-security-testing-guide/" target="_blank" rel="noreferrer">OWASP Web Security Testing Guide</a>.</p><h2 id="evidence" tabindex="-1"><span class="hub-section-number">2 </span>Evidence <a class="header-anchor" href="#evidence" aria-label="Permalink to “2 Evidence”">​</a></h2><p>Record source/runtime/tool versions, prerequisites and input, expected versus actual behavior, at least one failure→fix→retest, commands/exit status and retained artifacts. Distinguish local/mocked/source checks from native browser, external-service and deployment results. Screen-reader, zoom, real-device and cross-engine checks remain open unless actually performed. No remote push or paid-service activation.</p>',7)])])}const _=t(s,[["render",i]]);export{p as __pageData,_ as default};
